-- Migration 007: Add GST e-Invoice fields to OutwardHeader
-- IRN: 64-character Invoice Reference Number generated by IRP (Invoice Registration Portal)
-- AckNo: Government acknowledgement number
-- AckDate: Government acknowledgement timestamp
-- SignedQRCode: Cryptographically signed QR code text from NIC portal
-- SignedInvoice: Full signed JWT string from NIC portal
-- EInvoiceStatus: 'Pending', 'Generated', 'Cancelled', 'Failed'
-- EInvoiceCancelReason: Cancellation reason (1=Duplicate, 2=Data entry mistake, 3=Order cancelled, 4=Others)
-- EInvoiceCancelDate: Timestamp of cancellation on portal

ALTER TABLE "OutwardHeader" ADD COLUMN "IRN" VARCHAR(64) DEFAULT NULL;
ALTER TABLE "OutwardHeader" ADD COLUMN "AckNo" VARCHAR(30) DEFAULT NULL;
ALTER TABLE "OutwardHeader" ADD COLUMN "AckDate" VARCHAR(30) DEFAULT NULL;
ALTER TABLE "OutwardHeader" ADD COLUMN "SignedQRCode" TEXT DEFAULT NULL;
ALTER TABLE "OutwardHeader" ADD COLUMN "SignedInvoice" TEXT DEFAULT NULL;
ALTER TABLE "OutwardHeader" ADD COLUMN "EInvoiceStatus" VARCHAR(20) DEFAULT 'Pending';
ALTER TABLE "OutwardHeader" ADD COLUMN "EInvoiceCancelReason" VARCHAR(100) DEFAULT NULL;
ALTER TABLE "OutwardHeader" ADD COLUMN "EInvoiceCancelDate" VARCHAR(30) DEFAULT NULL;

